4fa1c8753341e307eba4e1f33b1a1cf6a:19:{s:9:"lbl_apply";s:5:"Apply";s:15:"lbl_apply_patch";s:11:"Apply patch";s:19:"lbl_apply_sql_patch";s:15:"Apply SQL patch";s:29:"lbl_check_for_upgrade_patches";s:25:"Check for upgrade patches";s:19:"lbl_current_version";s:15:"Current version";s:6:"lbl_no";s:2:"No";s:24:"lbl_no_available_patches";s:20:"No available patches";s:6:"lbl_or";s:2:"OR";s:14:"lbl_patch_file";s:10:"Patch file";s:24:"lbl_patch_upgrade_center";s:20:"Patch/Upgrade center";s:13:"lbl_patch_url";s:9:"Patch URL";s:11:"lbl_reverse";s:7:"Reverse";s:15:"lbl_sql_queries";s:14:"SQL query(ies)";s:18:"lbl_target_version";s:14:"Target version";s:11:"lbl_upgrade";s:7:"Upgrade";s:7:"lbl_yes";s:3:"Yes";s:24:"txt_apply_sql_patch_note";s:191:"This section is used to apply SQL patches to the database structure.<br /><br /><b>Note:</b> It is recommended to <a href="db_backup.php">backup the database</a> before applying an SQL patch.";s:20:"txt_patch_apply_note";s:368:"This section is used to apply patches (diff files) to the original source files. To use this function correctly you need to have a "patch" program. You also need to be able to change files permissions by request.<br /><br /><b>Note:</b> selecting  'Yes' in the 'Reverse' checkbox enables you to revert your files to the state they were in before the patch was applied.";s:33:"txt_patch_upgrade_center_top_text";s:486:"This section allows you to upgrade your software to the newest versions. Before using it you should download the upgrade file and unpack it into X-Cart directory. To use this function correctly you need to have a "patch" program. You also need to be able to change file permissions by request.<br /><br /> <b>Note:</b> Please use this function ONLY if you absolutely understand what you are doing. It is recommended to make a backup copy of all .php scripts before applying any patches.";}